// TestListIDs_ReservedTableNameDoesNotLeakAcrossResourceTypes guards a
// data-integrity bug: ListIDs resolves resourceType to a table via an
// exact-name sqlite_master lookup, then reads every row from that table
// with no resource_type filter -- correct for a real per-resource-type
// domain table (comparison, delivery, items, ...), but if resourceType
// happens to equal one of the store's own framework table names (e.g. a
// spec whose collection is literally named "resources"), the same lookup
// matches the framework table and returns every id across every resource
// type ever synced instead of erroring or falling back to a properly
// scoped read. Any dependent-resource sync that calls
// db.ListIDs("resources") to enumerate parents would then fan out child
// requests using an ID list drawn from unrelated resource types.
func TestListIDs_ReservedTableNameDoesNotLeakAcrossResourceTypes(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "data.db")
	s, err := Open(dbPath)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	defer s.Close()

	// Seed two different (untyped) resource types into the generic
	// resources table -- the framework table this bug would otherwise
	// read from unscoped when resourceType=="resources".
	if err := s.Upsert("biz", "shared", []byte(`{"kind":"biz"}`)); err != nil {
		t.Fatalf("upsert biz: %v", err)
	}
	if err := s.Upsert("bookmark", "other", []byte(`{"kind":"bookmark"}`)); err != nil {
		t.Fatalf("upsert bookmark: %v", err)
	}

	// "resources" collides with the framework's own table name but no row
	// actually has resource_type=='resources', so a correctly-scoped
	// lookup must return nothing -- not the union of every other type's
	// ids ("shared", "other") that an unscoped read of the reserved table
	// would return.
	ids, err := s.ListIDs("resources")
	if err != nil {
		t.Fatalf("ListIDs(\"resources\"): %v", err)
	}
	if len(ids) != 0 {
		t.Fatalf("ListIDs(\"resources\") = %v, want empty (leaked ids from other resource types via the reserved table name collision)", ids)
	}

	// Sanity: a genuine (non-colliding) resource type still resolves
	// correctly through the same fallback path.
	ids, err = s.ListIDs("biz")
	if err != nil {
		t.Fatalf("ListIDs(\"biz\"): %v", err)
	}
	if len(ids) != 1 || ids[0] != "shared" {
		t.Fatalf("ListIDs(\"biz\") = %v, want [shared]", ids)
	}
}

